const update = $input.first().json;

if (update.edited_message || update.channel_post || update.edited_channel_post) {
  return [];
}

const message = update.message;
if (!message || typeof message !== 'object') {
  return [];
}

if (message.from?.is_bot === true) {
  return [];
}

const chat = message.chat;
if (!chat || chat.type !== 'private') {
  return [];
}

const contact = message.contact && typeof message.contact === 'object' ? message.contact : null;
const text = message.text;
if (!contact && (!text || String(text).trim() === '')) {
  return [];
}

function optionalText(value) {
  if (value == null) return null;
  const out = String(value).trim();
  return out === '' ? null : out;
}

function sanitizeRawPayload(value) {
  if (value == null || typeof value !== 'object') {
    return {};
  }
  const secretPattern = /^(token|secret|password|authorization|api[_-]?key)$/i;
  if (Array.isArray(value)) {
    return value.map((entry) =>
      typeof entry === 'object' && entry !== null ? sanitizeRawPayload(entry) : entry
    );
  }
  const out = {};
  for (const [key, val] of Object.entries(value)) {
    if (secretPattern.test(key)) {
      out[key] = '[REDACTED]';
    } else if (typeof val === 'object' && val !== null) {
      out[key] = sanitizeRawPayload(val);
    } else {
      out[key] = val;
    }
  }
  return out;
}

const chatId = String(chat.id);
const from = message.from || {};
const telegramUserId = String(from.id);
const username = optionalText(from.username);
const contactFirstName = optionalText(contact?.first_name);
const contactLastName = optionalText(contact?.last_name);
const firstName = contactFirstName || optionalText(from.first_name);
const lastName = contactLastName || optionalText(from.last_name);
const name = [firstName, lastName].filter(Boolean).join(' ').trim() || null;
const phone = optionalText(contact?.phone_number);
const contactTelegramUserId = optionalText(contact?.user_id);
const timestamp = message.date ? new Date(message.date * 1000).toISOString() : new Date().toISOString();
const isContactShared = Boolean(contact && phone);
const messageText = isContactShared
  ? '[telegram_contact_shared]'
  : String(text).trim();

return [
  {
    json: {
      business_id: 'orange-park',
      channel: 'telegram',
      customer: {
        external_customer_id: `telegram:${telegramUserId}`,
        name,
        first_name: firstName,
        last_name: lastName,
        phone,
        email: null,
        telegram_id: telegramUserId,
        telegram_username: username,
        contact_shared: isContactShared
      },
      message: {
        text: messageText,
        external_message_id: `tg:${chatId}:${message.message_id}`,
        external_conversation_id: `tg:${chatId}`,
        timestamp,
        raw_payload: sanitizeRawPayload({
          provider: 'telegram',
          update_id: update.update_id,
          chat_id: chatId,
          chat_type: chat.type,
          message_id: message.message_id,
          telegram_id: telegramUserId,
          telegram_username: username,
          first_name: firstName,
          last_name: lastName,
          contact: isContactShared ? {
            phone_number: phone,
            first_name: contactFirstName,
            last_name: contactLastName,
            user_id: contactTelegramUserId
          } : null
        })
      },
      telegram_chat_id: chatId
    }
  }
];

const backend = $input.first().json;
const normalize = $('Normalize Telegram Message').first().json;
const fallback = 'Зараз не можу відповісти автоматично. Передам питання менеджеру.';

function unwrap(value) {
  if (!value || typeof value !== 'object') return value;
  if (value.body && typeof value.body === 'object') return value.body;
  if (typeof value.body === 'string') {
    try {
      return JSON.parse(value.body);
    } catch {
      return value;
    }
  }
  return value;
}

const body = unwrap(backend);
const reply = body?.success === true && body?.data?.reply_to_customer
  ? String(body.data.reply_to_customer).trim()
  : '';
const needsContact = body?.success === true
  && body?.data?.metadata?.telegram_contact_request?.needed === true;

return [
  {
    json: {
      telegram_chat_id: normalize.telegram_chat_id,
      reply_to_customer: reply || fallback,
      reply_markup: needsContact ? {
        keyboard: [[
          {
            text: '📱 Поділитися номером',
            request_contact: true
          }
        ]],
        resize_keyboard: true,
        one_time_keyboard: true
      } : undefined
    }
  }
];
